declare namespace SigApi {
    interface Event {
        readonly name: string
        readonly maId: number
        readonly miId: number
        readonly desc: string
        readonly src: number
        readonly accNo: number
        readonly flags: number
        /**
         * @returns {string}
         */
        getName(): string
        /**
         * @returns {number}
         */
        getMaId(): number
        /**
         * @returns {number}
         */
        getMiId(): number
        /**
         * @returns {string}
         */
        getDesc(): string
        /**
         * window.sigApi.SIG_CONST.EVENT_SRC_INTERN | window.sigApi.SIG_CONST.EVENT_SRC_EXTERN
         * @returns {number}
         */
        getSrc(): number
        /**
         * @returns {number}
         */
        getAccNo(): number
        /**
         * @returns {boolean}
         */
        getCanSetAccessnum(): boolean
        /**
         * @returns {boolean}
         */
        checkAccess(): boolean
    }
}
